Hashes Deep:
data = { a: 1, b: 2, c: 3 }

# fetch with block
value = data.fetch(:missing) { |key| "#{key} not found" }

# Transform values
data.transform_values! { |v| v * 10 }
# { a: 10, b: 20, c: 30 }

# Transform keys
data.transform_keys! { |k| k.to_s.upcase }
# { "A" => 10, "B" => 20, "C" => 30 }

# Hash slicing (Ruby 2.5+)
slice = data.slice("A", "B")
# { "A" => 10, "B" => 20 }

# dig for nested access
nested = { user: { profile: { name: "Alice" } } }
puts nested.dig(:user, :profile, :name)  # Alice
puts nested.dig(:user, :missing, :name)  # nil (no error)

# Merging with block
h1 = { a: 1, b: 2 }
h2 = { b: 3, c: 4 }
merged = h1.merge(h2) { |_key, old, new| old + new }
# { a: 1, b: 5, c: 4 }

attr_accessor/reader/writer:
class Product
  # Single attribute
  attr_accessor :name

  # Multiple attributes
  attr_reader :id, :created_at
  attr_writer :price

  def initialize(id, name, price)
    @id = id
    @name = name
    @price = price
    @created_at = Time.now
  end

  # Custom setter with validation
  def price=(value)
    raise "Price must be positive" if value < 0
    @price = value
  end
end

product = Product.new(1, "Widget", 9.99)
puts product.name        # Widget (attr_reader)
product.name = "Gadget"  # attr_writer (from attr_accessor)
puts product.id          # 1 (attr_reader only)
# product.id = 2  # NoMethodError (no writer)

method_missing:
class DynamicProxy
  def initialize(target)
    @target = target
  end

  def method_missing(name, *args, &block)
    if @target.respond_to?(name)
      @target.send(name, *args, &block)
    else
      super
    end
  end

  def respond_to_missing?(name, include_private = false)
    @target.respond_to?(name) || super
  end
end

proxy = DynamicProxy.new([1, 2, 3])
puts proxy.length    # 3 (delegated to Array)
puts proxy.join(',') # "1,2,3"
puts proxy.respond_to?(:length)  # true

DSL Patterns:
class RouterDSL
  attr_reader :routes

  def initialize
    @routes = []
  end

  def get(path, to:)
    @routes << { method: 'GET', path: path, controller: to }
  end

  def post(path, to:)
    @routes << { method: 'POST', path: path, controller: to }
  end

  def self.draw(&block)
    dsl = new
    dsl.instance_eval(&block)
    dsl.routes
  end
end

routes = RouterDSL.draw do
  get "/users", to: "users#index"
  get "/users/new", to: "users#new"
  post "/users", to: "users#create"
end

puts routes.inspect
# [{:method=>"GET", :path=>"/users", ...}, ...]
